import{_ as s,I as t,o as r,c as d,b6 as e,j as h,J as i,w as o}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"スマート旅行計画 Agent プラットフォーム開発実践","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/stage-2/assignments/travel-planning-agent-platform/index.md","filePath":"ja-jp/stage-2/assignments/travel-planning-agent-platform/index.md"}'),p={name:"ja-jp/stage-2/assignments/travel-planning-agent-platform/index.md"},c={style:{margin:"32px 0"}};function b(g,a,k,m,f,u){const l=t("StepBar"),n=t("ClientOnly");return r(),d("div",null,[a[0]||(a[0]=e('<h1 id="スマート旅行計画-agent-プラットフォーム開発実践" tabindex="-1">スマート旅行計画 Agent プラットフォーム開発実践 <a class="header-anchor" href="#スマート旅行計画-agent-プラットフォーム開発実践" aria-label="Permalink to “スマート旅行計画 Agent プラットフォーム開発実践”">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to “概要”">​</a></h2><p>本実践プロジェクトでは、実際の PRD に基づいて、スマート旅行計画 Agent プラットフォームを一から完成させます。構造化された入力を受け取り、毎日の旅程を生成し、保存と再利用をサポートする完全な AI 製品を構築します。単なるチャットボットではなく、タスク管理能力を持つ製品です。</p><p>これは Stage 2 の総合実践セクションです。このプロジェクトのコアチャレンジは、AI が構造化された使用可能な旅程計画を生成するようにすることであり、操作不可能な長いテキストではなく、実用的な出力を生み出すことにあります。</p><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to “前提知識”">​</a></h2><p>このプロジェクトを始める前に、以下の内容をすでに習得している必要があります：</p><ul><li>フロントエンドページ設計とコンポーネントライブラリの使用（<a href="./../../frontend/ui-design/">UI 設計</a>、<a href="./../../frontend/modern-component-library/">モダンコンポーネントライブラリ</a>）</li><li>バックエンドインターフェース設計と開発（<a href="./../../backend/ai-interface-code/">インターフェースコード作成</a>）</li><li>データベース基礎と Supabase（<a href="./../../backend/database-supabase/">データベースから Supabase まで</a>）</li><li>Git ワークフローとデプロイ（<a href="./../../backend/git-workflow/">Git と GitHub</a>、<a href="./../../backend/zeabur-deployment/">Web アプリのデプロイ</a>）</li></ul><h2 id="学習目標" tabindex="-1">学習目標 <a class="header-anchor" href="#学習目標" aria-label="Permalink to “学習目標”">​</a></h2><p>本実践完了後、以下のことができるようになります：</p><ol><li>PRD を読み、Agent プラットフォームの開発タスクリストを抽出する</li><li>構造化された入力フォームと構造化された出力形式を設計する</li><li>Agent オーケストレーション層を実装し、ユーザー入力、モデル呼び出し、結果保存を処理する</li><li>「生成 → 保存 → 再利用」のビジネスクロージャを構築する</li><li>エンドツーエンドの結合テストを完了し、デモ可能な AI 製品プロトタイプを納品する</li></ol><h2 id="プロジェクト概要" tabindex="-1">プロジェクト概要 <a class="header-anchor" href="#プロジェクト概要" aria-label="Permalink to “プロジェクト概要”">​</a></h2><p>あなたが構築する製品は、スマート旅行計画 Agent プラットフォームです：</p><table tabindex="0"><thead><tr><th>機能</th><th>説明</th></tr></thead><tbody><tr><td><strong>旅程計画</strong></td><td>ユーザーが出発地、目的地、日付、予算、好みを入力し、システムが毎日の旅程を生成</td></tr><tr><td><strong>予算配分</strong></td><td>旅程結果に予算配分と提案を含む</td></tr><tr><td><strong>履歴管理</strong></td><td>ユーザーは過去の計画を保存、再生成、エクスポート可能</td></tr><tr><td><strong>管理バックエンド</strong></td><td>管理者が人気の目的地、失敗タスク、ユーザーフィードバックを確認</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本プロジェクトの要件文書は GitHub にあります： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/ja-jp/stage-2/assignments/travel-planning-agent-platform/PRD.md" target="_blank" rel="noreferrer">PRD を表示</a></p></div>',14)),h("div",c,[i(n,null,{default:o(()=>[i(l,{active:0,items:[{title:"要件分析",description:"PRD を読み、ページ、Agent オーケストレーション、入出力構造を明確にする"},{title:"スケルトン構築",description:"AI でホーム、計画ページ、履歴ページ、管理ページのスケルトンを生成"},{title:"反復開発",description:"構造化出力、タスクステータス、履歴管理をモジュールごとに追加"},{title:"結合とリリース",description:"エンドツーエンドで動作確認し、デプロイしてデモを準備"}]})]),_:1})]),a[1]||(a[1]=e(`<h2 id="第-1-部-要件分析" tabindex="-1">第 1 部：要件分析 <a class="header-anchor" href="#第-1-部-要件分析" aria-label="Permalink to “第 1 部：要件分析”">​</a></h2><h3 id="_1-1-prd-を読む" tabindex="-1">1.1 PRD を読む <a class="header-anchor" href="#_1-1-prd-を読む" aria-label="Permalink to “1.1 PRD を読む”">​</a></h3><p>PRD 文書を開き、以下の質問に重点的に答えてください：</p><ul><li>第 1 版は単一目的地のみにしますか？</li><li>旅程出力は構造化されている必要がありますか？その構造は何ですか？</li><li>エクスポート機能はどの程度深く実装しますか？（共有リンク / PDF / 画像）</li><li>管理バックエンドの統計とタスクログの範囲は何ですか？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>以上の質問に対する明確な答えがない場合は、コードを書き始めないでください。要件の理解が不明確なのは、手戻りの最も一般的な原因です。</p></div><h3 id="_1-2-システムアーキテクチャの確認" tabindex="-1">1.2 システムアーキテクチャの確認 <a class="header-anchor" href="#_1-2-システムアーキテクチャの確認" aria-label="Permalink to “1.2 システムアーキテクチャの確認”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; planner[&quot;計画ページ&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  planner --&gt; agent[&quot;Agent オーケストレーション層&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent --&gt; model[&quot;モデル呼び出し&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent --&gt; db[&quot;データベース&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  db --&gt; history[&quot;履歴計画&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  db --&gt; admin[&quot;管理統計とログ&quot;]</span></span></code></pre></div><h2 id="第-2-部-プロジェクトスケルトンの構築" tabindex="-1">第 2 部：プロジェクトスケルトンの構築 <a class="header-anchor" href="#第-2-部-プロジェクトスケルトンの構築" aria-label="Permalink to “第 2 部：プロジェクトスケルトンの構築”">​</a></h2><h3 id="_2-1-フロントエンドページの生成" tabindex="-1">2.1 フロントエンドページの生成 <a class="header-anchor" href="#_2-1-フロントエンドページの生成" aria-label="Permalink to “2.1 フロントエンドページの生成”">​</a></h3><p>プロンプト参考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>現在の PRD に基づいて、スマート旅行計画 Agent プラットフォームのフロントエンドスケルトンを生成してください。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要件：</span></span>
<span class="line"><span>1. ページには以下を含む：ホーム、計画ページ、旅程詳細ページ、履歴記録ページ、管理ページ</span></span>
<span class="line"><span>2. 計画ページの左側にフォーム、右側に結果プレビュー</span></span>
<span class="line"><span>3. まずページ構造とモックデータのみを生成し、実際のインターフェースには接続しない</span></span>
<span class="line"><span>4. モダンな AI 製品のようなスタイルにする</span></span></code></pre></div><h3 id="_2-2-ページ構造の検証" tabindex="-1">2.2 ページ構造の検証 <a class="header-anchor" href="#_2-2-ページ構造の検証" aria-label="Permalink to “2.2 ページ構造の検証”">​</a></h3><p>項目ごとにチェック：</p><ul><li>[ ] 計画ページのフォームフィールドが PRD と一致している</li><li>[ ] 結果プレビュー領域で構造化された旅程データが表示できる</li><li>[ ] 履歴記録ページで複数の計画が表示できる</li><li>[ ] 管理バックエンドページで統計データが表示できる</li></ul><h2 id="第-3-部-反復開発" tabindex="-1">第 3 部：反復開発 <a class="header-anchor" href="#第-3-部-反復開発" aria-label="Permalink to “第 3 部：反復開発”">​</a></h2><h3 id="_3-1-モジュールごとに進める" tabindex="-1">3.1 モジュールごとに進める <a class="header-anchor" href="#_3-1-モジュールごとに進める" aria-label="Permalink to “3.1 モジュールごとに進める”">​</a></h3><ol><li><strong>認証</strong>：登録、ログイン</li><li><strong>計画フォーム</strong>：構造化入力（出発地、目的地、日付、予算、好み）</li><li><strong>Agent オーケストレーション</strong>：入力の受信 → モデル呼び出し → 構造化出力の解析</li><li><strong>結果表示</strong>：旅程を日ごとに表示、予算配分、提案</li><li><strong>履歴管理</strong>：計画の保存、再生成、エクスポート</li><li><strong>管理バックエンド</strong>：人気の目的地、失敗タスク、ユーザーフィードバック</li><li><strong>タスクステータス</strong>：生成中 / 成功 / 失敗のステータス管理とエラー記録</li></ol><h3 id="_3-2-モジュール自己チェック" tabindex="-1">3.2 モジュール自己チェック <a class="header-anchor" href="#_3-2-モジュール自己チェック" aria-label="Permalink to “3.2 モジュール自己チェック”">​</a></h3><table tabindex="0"><thead><tr><th>チェック項目</th><th>検証方法</th></tr></thead><tbody><tr><td>入力完全性</td><td>フォームフィールドが PRD と一致しているか</td></tr><tr><td>出力構造化</td><td>旅程結果が構造化データであるか（長いテキストではないか）</td></tr><tr><td>データ整合性</td><td>trip、itinerary、logs のデータが一致しているか</td></tr><tr><td>クロージャ検証</td><td>「入力 → 生成 → 保存 → 再生成」のデモができるか</td></tr></tbody></table><h2 id="第-4-部-結合テストとリリース" tabindex="-1">第 4 部：結合テストとリリース <a class="header-anchor" href="#第-4-部-結合テストとリリース" aria-label="Permalink to “第 4 部：結合テストとリリース”">​</a></h2><h3 id="_4-1-エンドツーエンドテスト" tabindex="-1">4.1 エンドツーエンドテスト <a class="header-anchor" href="#_4-1-エンドツーエンドテスト" aria-label="Permalink to “4.1 エンドツーエンドテスト”">​</a></h3><p>少なくとも以下のシナリオを検証：</p><ul><li>旅程パラメータを入力 → 毎日の旅程を生成 → 予算配分を確認 → 履歴に保存</li><li>履歴記録から旅程を再生成</li><li>管理者がタスク統計と失敗ログを確認</li></ul><h2 id="提出物" tabindex="-1">提出物 <a class="header-anchor" href="#提出物" aria-label="Permalink to “提出物”">​</a></h2><p>本プロジェクト完了後、以下の内容を提出する必要があります：</p><ul><li>[ ] アクセス可能なオンラインデモリンク</li><li>[ ] ソースコードリポジトリリンク（README を含む）</li><li>[ ] PRD 文書</li><li>[ ] コアページのスクリーンショット（計画ページ、旅程詳細ページ、履歴記録ページ、管理バックエンド）</li><li>[ ] 60 秒のデモ動画</li></ul><h2 id="評価基準" tabindex="-1">評価基準 <a class="header-anchor" href="#評価基準" aria-label="Permalink to “評価基準”">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>基本要件</th><th>応用要件</th></tr></thead><tbody><tr><td>PRD 整合性</td><td>ページ、機能、データ構造が基本的に PRD に適合</td><td>設計決定を明確に説明できる</td></tr><tr><td>製品クロージャ</td><td>計画 → 保存 → 履歴 → 再生成が動作する</td><td>エクスポートと共有をサポート</td></tr><tr><td>出力品質</td><td>旅程結果が構造化され読みやすい</td><td>予算配分が合理的で、提案に针对性がある</td></tr><tr><td>管理機能</td><td>タスク統計と失敗ログが確認可能</td><td>人気の目的地分析がある</td></tr><tr><td>エンジニアリング完成度</td><td>フロントエンド、バックエンド、データベース、モデル呼び出しパイプラインが接続されている</td><td>タスクステータス管理が充実し、エラーがトレース可能</td></tr></tbody></table><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to “参考資料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 設計</a></li><li><a href="./../../frontend/modern-component-library/">モダンコンポーネントライブラリでインターフェースを更新</a></li><li><a href="./../../backend/database-supabase/">データベースから Supabase まで</a></li><li><a href="./../../backend/ai-interface-code/">大規模モデルによるインターフェースコードとドキュメント作成</a></li><li><a href="./../../backend/git-workflow/">Git と GitHub ワークフロー</a></li><li><a href="./../../backend/zeabur-deployment/">Web アプリのデプロイ方法</a></li></ul>`,30))])}const x=s(p,[["render",b]]);export{P as __pageData,x as default};
